import{_ as t,o as i,c as a,ag as o}from"./chunks/framework.NIGIbcGl.js";const p=JSON.parse('{"title":"Custom Booking Status & Confirmation","description":"","frontmatter":{},"headers":[],"relativePath":"customer/custom-booking-status/index.md","filePath":"customer/custom-booking-status/index.md"}'),s={name:"customer/custom-booking-status/index.md"};function n(d,e,r,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="custom-booking-status-confirmation" tabindex="-1">Custom Booking Status &amp; Confirmation <a class="header-anchor" href="#custom-booking-status-confirmation" aria-label="Permalink to &quot;Custom Booking Status &amp; Confirmation&quot;">​</a></h1><p>This guide covers the <strong>customer-facing</strong> view of a custom booking&#39;s lifecycle — what each status means, when you receive your ticket, and how to confirm receipt to close out the booking.</p><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th><th>Auth</th></tr></thead><tbody><tr><td><strong>Confirm ticket received</strong> (legacy — see note below)</td><td><code>PATCH /api/v1/custom-booking/:id/confirm-received</code></td><td>Authenticated <strong>or</strong> guest (email + phone)</td></tr></tbody></table><blockquote><p><strong>What changed.</strong> Under the current flow, admin ticket upload transitions the booking directly to <code>COMPLETED</code> and emails you the ticket. You no longer need to confirm receipt. The <code>PATCH .../confirm-received</code> endpoint is kept only for bookings that were already in <code>TICKET_RECEIVED</code> under the previous flow.</p></blockquote><hr><h2 id="lifecycle-from-your-perspective" tabindex="-1">Lifecycle from Your Perspective <a class="header-anchor" href="#lifecycle-from-your-perspective" aria-label="Permalink to &quot;Lifecycle from Your Perspective&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means for you</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>We received your booking. Please upload your passenger manifest to move forward.</td></tr><tr><td><code>UPLOADED_MANIFEST</code></td><td>Your manifest has been uploaded. We&#39;re checking seat availability.</td></tr><tr><td><code>CONFIRMED</code></td><td>Seats confirmed. We have assigned a ticket channel and issued your invoice. You may cancel at this stage via <code>PATCH /custom-booking/:id/status</code>.</td></tr><tr><td><code>WAITING_FOR_PAYMENT</code></td><td>Your invoice is ready — please complete payment.</td></tr><tr><td><code>PAID</code></td><td>Payment received. We&#39;re processing with the ticket channel.</td></tr><tr><td><code>DOWNLOADED_MANIFEST</code></td><td>We&#39;ve sent your manifest to the channel.</td></tr><tr><td><code>WAITING_FOR_TICKET</code></td><td>Channel is preparing your ticket.</td></tr><tr><td><code>TICKET_RECEIVED</code></td><td><strong>Legacy only.</strong> Older bookings that are still waiting for your receipt confirmation. New bookings never enter this state — admin ticket upload now moves them straight to <code>COMPLETED</code>.</td></tr><tr><td><code>COMPLETED</code></td><td>Booking finalized. Your ticket has been uploaded and emailed to you — check your inbox (and spam) for the attachment.</td></tr><tr><td><code>CANCELLED</code></td><td>Booking cancelled.</td></tr><tr><td><code>EXPIRED</code></td><td>Payment window elapsed before payment was received.</td></tr><tr><td><code>NOT_AVAILABLE</code></td><td>The channel could not provide seats for this booking.</td></tr></tbody></table><hr><h2 id="ticket-email" tabindex="-1">Ticket Email <a class="header-anchor" href="#ticket-email" aria-label="Permalink to &quot;Ticket Email&quot;">​</a></h2><p>When admin uploads your ticket, the booking moves to <code>COMPLETED</code> and you&#39;ll receive an email with subject:</p><blockquote><p><strong>Tiket Pemesanan Anda Telah Tersedia - {bookingCode}</strong></p></blockquote><p>The email includes:</p><ul><li>Booking code, route, departure date, passenger count, total price.</li><li>The ticket file as a downloadable attachment.</li></ul><p>The email is delivered asynchronously via our third-party provider and is <strong>not automatically retried</strong> by the queue worker — if you don&#39;t see it within a few minutes, check spam first, then contact support with your booking code and they can trigger a manual resend. See <a href="/ahlaan-train-docs/customer/tickets-email/">Tickets &amp; Email</a> for general email/ ticket-download guidance.</p><hr><h2 id="confirm-ticket-received-legacy" tabindex="-1">Confirm Ticket Received (legacy) <a class="header-anchor" href="#confirm-ticket-received-legacy" aria-label="Permalink to &quot;Confirm Ticket Received (legacy)&quot;">​</a></h2><blockquote><p><strong>Most customers can skip this section.</strong> It only applies to bookings that were left in <code>TICKET_RECEIVED</code> under the previous flow. New bookings are set to <code>COMPLETED</code> automatically when admin uploads the ticket.</p></blockquote><p>Once you&#39;ve received and verified your ticket, confirm receipt to move the booking to <code>COMPLETED</code>. The booking must currently be in <code>TICKET_RECEIVED</code>.</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /custom-booking/:id/confirm-received</span></span></code></pre></div><h3 id="authenticated-user" tabindex="-1">Authenticated user <a class="header-anchor" href="#authenticated-user" aria-label="Permalink to &quot;Authenticated user&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/custom-booking/booking-123/confirm-received</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;jwt-token&gt;&quot;</span></span></code></pre></div><h3 id="guest-user" tabindex="-1">Guest user <a class="header-anchor" href="#guest-user" aria-label="Permalink to &quot;Guest user&quot;">​</a></h3><p>Guest access requires both <code>email</code> and <code>phone</code> query parameters matching the booking&#39;s <code>contactPerson</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/custom-booking/booking-123/confirm-received?email=guest@example.com&amp;phone=628123456789&#39;</span></span></code></pre></div><h3 id="response-200" tabindex="-1">Response (200) <a class="header-anchor" href="#response-200" aria-label="Permalink to &quot;Response (200)&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;booking-123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;bookingCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ABC1234&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPLETED&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ticketChannel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0190abc1-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HHR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><ul><li><code>400 Bad Request</code> — Booking is not in <code>TICKET_RECEIVED</code>.</li><li><code>401 Unauthorized</code> — Guest verification (email + phone) is required and missing.</li><li><code>403 Forbidden</code> — Authenticated user is not the booking owner.</li><li><code>404 Not Found</code> — Booking not found, or guest email/phone do not match.</li></ul><hr><h2 id="auto-completion-legacy" tabindex="-1">Auto-Completion (legacy) <a class="header-anchor" href="#auto-completion-legacy" aria-label="Permalink to &quot;Auto-Completion (legacy)&quot;">​</a></h2><p>For bookings still in <code>TICKET_RECEIVED</code> under the legacy flow: if you don&#39;t confirm within 24 hours after the departure date, the system automatically transitions the booking <code>TICKET_RECEIVED → COMPLETED</code>. The booking response will include an <code>autoCompletedAt</code> timestamp in that case, instead of being null.</p><p>New bookings are set to <code>COMPLETED</code> immediately when admin uploads the ticket, so <code>autoCompletedAt</code> stays <code>null</code> and this cron does not apply.</p><p>You can still view the booking after auto-completion; no further customer action is required.</p><hr><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Limit</th><th>Window</th></tr></thead><tbody><tr><td><code>PATCH /custom-booking/:id/confirm-received</code></td><td>10</td><td>60s</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/custom-manifest/">Custom Booking Manifests (Customer)</a> — upload your passenger manifest.</li><li><a href="/ahlaan-train-docs/customer/tickets-email/">Tickets &amp; Email</a> — ticket downloads and email resends.</li><li><a href="/ahlaan-train-docs/admin/custom-booking/">Custom Booking Management (Admin)</a> — admin-facing companion.</li></ul>`,41)])])}const k=t(s,[["render",n]]);export{p as __pageData,k as default};
